"kind": "propose",
"summary": "Liveness probe timeout is too short, causing premature termination during startup",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Logs show the app was still starting when liveness probe failed",
    "supporting": ["probe_kills", "killed_during_startup", "ev-container_logs_tail"],
    "contradicting": ["probe_timeouts"],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "finance",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Allow the app 5 seconds to complete startup before liveness probe times out",
  "rationale": "Logs show the app was still loading data (account index) when the probe failed. The current 1s timeout is insufficient for the app's startup sequence.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["probe_kills", "killed_during_startup"]
}
}
